select 'public.venues' as table_name,count(*) as row_count,md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' order by md5(to_jsonb(t)::text)),'')) as row_fingerprint from public.venues t union all select 'public.users' as table_name,count(*) as row_count,md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' order by md5(to_jsonb(t)::text)),'')) as row_fingerprint from public.users t union all select 'public.flavors' as table_name,count(*) as row_count,md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' order by md5(to_jsonb(t)::text)),'')) as row_fingerprint from public.flavors t union all select 'public.stock' as table_name,count(*) as row_count,md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' order by md5(to_jsonb(t)::text)),'')) as row_fingerprint from public.stock t union all select 'public.moves' as table_name,count(*) as row_count,md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' order by md5(to_jsonb(t)::text)),'')) as row_fingerprint from public.moves t union all select 'public.mixes' as table_name,count(*) as row_count,md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' order by md5(to_jsonb(t)::text)),'')) as row_fingerprint from public.mixes t union all select 'public.guest_mixes' as table_name,count(*) as row_count,md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' order by md5(to_jsonb(t)::text)),'')) as row_fingerprint from public.guest_mixes t union all select 'public.flavor_strengths' as table_name,count(*) as row_count,md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' order by md5(to_jsonb(t)::text)),'')) as row_fingerprint from public.flavor_strengths t union all select 'public.flavor_packs' as table_name,count(*) as row_count,md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' order by md5(to_jsonb(t)::text)),'')) as row_fingerprint from public.flavor_packs t union all select 'mixora_private.stock_requests' as table_name,count(*) as row_count,md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' order by md5(to_jsonb(t)::text)),'')) as row_fingerprint from mixora_private.stock_requests t;
